typedef unsigned int u_int;
typedef unsigned long u_long;

class nglTexStreamPos
{
public:
  u_int addr, cycle;
};

inline bool operator==(const nglTexStreamPos &a, const nglTexStreamPos &b)
{
	return a.cycle == b.cycle && a.addr == b.addr;
}

struct sceGifPacket
{
  u_int* pCurrent;
};

struct nglVif1IntEntry
{
  u_int Type;
  u_int* GifDMA;
  u_int DataSize;
  u_int NTextures;
};

extern u_int nglDisplayWidth;
extern u_int nglDisplayHeight;
extern u_int nglLockBufferSize;
extern nglTexStreamPos nglTexStreamPrevStartRef;
extern nglTexStreamPos nglTexStreamCurStartRef;
extern nglTexStreamPos nglTexStreamAlloc;
extern sceGifPacket nglGifPkt;
extern u_int* nglGifPacketNext;
extern unsigned char* nglGifPacketWork;
extern u_int nglGifPacketWorkSize;
extern nglVif1IntEntry* nglVif1IntCurTexEntry;

extern "C" void sceGifPkCnt(sceGifPacket*, int, int, int);
extern "C" void sceGifPkAddGsData(sceGifPacket*, u_long);
extern "C" void sceGifPkEnd(sceGifPacket*, int, int, int);
extern "C" void sceGifPkTerminate(sceGifPacket*);
void nglFatal(const char*, ...);
void nglPrintf(const char*, ...);

#define NULL 0
#define NGL_FRAME_PIXELSIZE 4
#define NGL_VRAM_FRAME_SIZE ((nglDisplayWidth * nglDisplayHeight * NGL_FRAME_PIXELSIZE) / 256)
#define NGL_VRAM_LOCKED_START (NGL_VRAM_FRAME_SIZE * 3)
#define NGL_VRAM_LOCKED_END (NGL_VRAM_LOCKED_START + nglLockBufferSize)
#define NGL_VRAM_STREAM_START NGL_VRAM_LOCKED_END
#define NGL_DMA_MEM 0x0FFFFFFF
#define SCE_GIF_PACKED 0
#define SCE_GS_TEXFLUSH 0x3f
#define DEBUG_ENABLE(x) 0
#define SCE_GIF_SET_TAG(nloop,eop,pre,prim,flg,nreg) \
  (((u_long)(nloop)) | (((u_long)(eop)) << 15) | (((u_long)(pre)) << 46) | \
   (((u_long)(prim)) << 47) | (((u_long)(flg)) << 58) | (((u_long)(nreg)) << 60))

void nglVif1IntCloseTextureBlock()
{
  if (nglTexStreamCurStartRef==nglTexStreamAlloc)
  {
	  nglTexStreamAlloc.cycle += 2;
	  nglTexStreamAlloc.addr = NGL_VRAM_STREAM_START;
	  nglTexStreamPrevStartRef = nglTexStreamAlloc;
	  nglTexStreamCurStartRef = nglTexStreamAlloc;
  }
  else
  {
	  nglTexStreamPrevStartRef = nglTexStreamCurStartRef;
	  nglTexStreamCurStartRef = nglTexStreamAlloc;
  }

  // Flush the texture cache
  sceGifPkCnt( &nglGifPkt, 0, 0, 0 );
  sceGifPkAddGsData( &nglGifPkt, SCE_GIF_SET_TAG( 1, 1, NULL, NULL, SCE_GIF_PACKED, 1 ) );
  sceGifPkAddGsData( &nglGifPkt, 0xEL );
  sceGifPkAddGsData( &nglGifPkt, 0 );
  sceGifPkAddGsData( &nglGifPkt, SCE_GS_TEXFLUSH );

  // End DMA transfer
  sceGifPkEnd( &nglGifPkt, 0, 0, 0 );
  sceGifPkTerminate( &nglGifPkt );

  if ( ( (u_int)nglGifPkt.pCurrent & NGL_DMA_MEM ) - (u_int)nglGifPacketWork >= nglGifPacketWorkSize )
    nglFatal( "Gif packet workspace overflow (%d/%d).\n",( (u_int)nglGifPkt.pCurrent & NGL_DMA_MEM ) - (u_int)nglGifPacketWork, nglGifPacketWorkSize );

  // Align and close off the GIF packet, updating the global GIF packet workspace pointer..
  nglGifPacketNext = nglGifPkt.pCurrent;
  while ( (u_int)nglGifPacketNext & 15 ) *(nglGifPacketNext++) = 0;

  if ( ( DEBUG_ENABLE( DumpFrameLog ) & 1 ) && nglVif1IntCurTexEntry )
    nglPrintf( "LOG: End of block.  NTex: %d, Size: %d (%d bytes).\n", nglVif1IntCurTexEntry->NTextures, nglVif1IntCurTexEntry->DataSize, nglVif1IntCurTexEntry->DataSize*256 );
}
